using System;
using System.Runtime.InteropServices;
using System.Text;
public class CredMan {
  [StructLayout\(LayoutKind.Sequential, CharSet=CharSet.Unicode\)]
  public struct CREDENTIAL {
    public uint Flags;
    public uint Type;
    [MarshalAs\(UnmanagedType.LPWStr\)] public string TargetName;
    [MarshalAs\(UnmanagedType.LPWStr\)] public string Comment;
    public System.Runtime.InteropServices.ComTypes.FILETIME LastWritten;
    public uint CredentialBlobSize;
    public IntPtr CredentialBlob;
    public uint Persist;
    public uint AttributeCount;
    public IntPtr Attributes;
    [MarshalAs\(UnmanagedType.LPWStr\)] public string TargetAlias;
    [MarshalAs\(UnmanagedType.LPWStr\)] public string UserName;
  }
  [DllImport\(\\"advapi32.dll\\", CharSet=CharSet.Unicode, SetLastError=true\)]
  public static extern bool CredRead\(string target, uint type, uint flags, out IntPtr ptr\);
  [DllImport\(\\"advapi32.dll\\"\)] public static extern void CredFree\(IntPtr ptr\);
  public static string GetPassword\(string target\) {
    IntPtr ptr;
    if \(!CredRead\(target, 1, 0, out ptr\)\) return null;
    var c = \(CREDENTIAL\)Marshal.PtrToStructure\(ptr, typeof\(CREDENTIAL\)\);
    var pw = Marshal.PtrToStringUni\(c.CredentialBlob, \(int\)c.CredentialBlobSize/2\);
    CredFree\(ptr\);
    return pw;
  }
}
'@
